//! Closed Shoggoth society, pinned to MSBQ02 original. Construction uses50+1.
use crate::{catalog,engine::RuleResult,model::*,rules::*,society::SocietyDefinition};
pub(crate) const ID:&str="MSBQ02";
pub(crate) const HONOR:&str="msbq02-honor-command";
pub(crate) const LOSS:&str="msbq02-red-loss";
pub(crate) const WIN:&str="msbq02-third-task";
fn same<T:serde::Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn society()->SocietyDefinition{let mut card:catalog::CardDefinition=serde_json::from_value(serde_json::json!({"id":ID,"name":"修格斯","kind":"society","type":"秘社/神话生物/实验体","subtypes":["神话生物","实验体"],"color":"灰","society":"修格斯","unique":true,"supported":false,"text":"构筑时选择副名称为修格斯的角色作为核心；只能包含灰、红、中立牌，至少12张命令。打出或付费翻面红牌强制增加1失控，上限3。3失控时核心混乱且只能打出或付费现身核心和命令。快速行动支付1名誉：本回合下一张打出的命令减费1。赢得至少3张任务牌时获胜。"})).unwrap();card.abilities=definition().abilities.iter().map(|a|catalog::AbilitySummary{key:a.key.clone(),label:a.label.clone(),timing:"fast".into(),costs:a.costs.clone(),triggered:a.event.is_some()}).collect();SocietyDefinition{card,subtitle:"神话生物克隆体".into(),printed_cost:None,starting_hand:5,deck_constraints:vec![crate::society::SocietyDeckConstraint::Shoggoth],unresolved_abilities:Default::default()}}
pub(crate) fn definition()->Definition{let mut a=ability(HONOR,"支付1名誉：本回合下一张命令减费1",Timing::Fast,vec![Cost::MSBQ02Honor],vec![],vec![Op::CostReduction{filter:CardFilter::MSBQ02Command,amount:1}],None);a.activation_only=true;with_abilities(vec![a,ability(LOSS,"强制：红牌打出或付费现身，失控增加1",Timing::Fast,vec![],vec![],vec![Op::MSBQ02Loss{played:None,event:None}],Some(Event::MSBQ02RedPlayed)),ability(WIN,"赢得至少三张任务：赢得游戏",Timing::Fast,vec![],vec![],vec![Op::MSBQ02TaskWin{scored:None}],Some(Event::MSBQ02TaskScored))])}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("msbq02-")||matches!(a.event,Some(Event::MSBQ02RedPlayed|Event::MSBQ02TaskScored))||a.costs.iter().any(|c|matches!(c,Cost::MSBQ02Honor))||a.ops.iter().any(|o|matches!(o,Op::MSBQ02Loss{..}|Op::MSBQ02TaskWin{..}|Op::CostReduction{filter:CardFilter::MSBQ02Command,..}))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.into_iter().find(|b|b.key==a.key).ok_or("未知修格斯能力")?;if a.key==LOSS{let [Op::MSBQ02Loss{played,event}]=a.ops.as_slice()else{return Err("失控观察程序缺失".into());};expected.ops=vec![Op::MSBQ02Loss{played:played.clone(),event:event.clone()}];}if a.key==WIN {let [Op::MSBQ02TaskWin{scored}]=a.ops.as_slice()else{return Err("胜利触发缺任务观察".into());};expected.ops=vec![Op::MSBQ02TaskWin{scored:scored.clone()}];}if id!=ID||!same(a,&expected){return Err("修格斯能力费用、时点、事件或程序被改写".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if (id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("修格斯完整定义不可改写或移植".into());}Ok(())}
impl Game{
 pub(crate) fn msbq02_observe_score(&mut self,actor:usize){if !self.has_shoggoth(actor)||self.players[actor].score_cards.last().is_none_or(|c|!catalog::card(&c.definition).subtypes.iter().any(|s|s=="任务")){return;}let cards=self.players[actor].score_cards.iter().filter(|c|catalog::card(&c.definition).subtypes.iter().any(|s|s=="任务")).cloned().collect::<Vec<_>>();if cards.len()<3{return;}let source=self.source_snapshot(self.players[actor].society_zone.card.as_ref().unwrap(),None);let mut ability=definition().abilities.remove(2);ability.ops=vec![Op::MSBQ02TaskWin{scored:Some(cards)}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor,source,ability}});}
 pub(crate) fn msbq02_task_win(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_msbq02_frame(f)?;if f.ability_key!=WIN||f.cursor!=1{return Err("任务胜利须由原观察触发".into());}if !self.players[f.actor].eliminated{self.finish(self.team(f.actor));}Ok(())}
 pub(crate) fn msbq02_core(&self,actor:usize,c:&Card)->bool{c.owner==actor&&self.core_zones.iter().any(|z|z.owner==actor&&z.definition==c.definition)}
 pub(crate) fn msbq02_chaos(&self,c:&Card)->bool{self.has_shoggoth(c.controller)&&self.players[c.controller].society_zone.loss_control==3&&self.msbq02_core(c.controller,c)}
 pub(crate) fn msbq02_allow_play(&self,actor:usize,c:&Card)->RuleResult<()>{self.msjz03_allow_play(actor,c)?;if self.has_shoggoth(actor)&&self.players[actor].society_zone.loss_control==3&&!self.msbq02_core(actor,c)&&!catalog::card(&c.definition).subtypes.iter().any(|s|s=="命令"){return Err("三失控时只能打出或付费现身核心角色和命令牌".into());}Ok(())}
 pub(crate) fn msbq02_pay_honor(&mut self,actor:usize,s:&SourceSnapshot,a:&AbilitySpec)->RuleResult<PaidCost>{validate_ability(ID,a)?;if a.key!=HONOR||s.card.definition!=ID||!self.has_shoggoth(actor)||self.players[actor].society_zone.card.as_ref()!=Some(&s.card)||s.region.is_some(){return Err("名誉费用只能来自本方真实修格斯秘社能力".into());}let before=self.players[actor].honor;if before==0{return Err("名誉不足".into());}self.players[actor].honor-=1;Ok(PaidCost::MSBQ02Honor{before})}
 pub(crate) fn msbq02_observe_play(&mut self,f:&ResolutionFrame){if !self.has_shoggoth(f.actor)||catalog::card(&f.source.card.definition).color!="红"{return;}let source=self.source_snapshot(self.players[f.actor].society_zone.card.as_ref().unwrap(),None);let mut ability=definition().abilities.remove(1);ability.ops=vec![Op::MSBQ02Loss{played:Some(Box::new(f.source.clone())),event:Some(f.frame_id.clone())}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:f.actor,source,ability}});}
 fn msbq02_source(&self,actor:usize,s:&SourceSnapshot,ops:&[Op])->RuleResult<()>{let c=&s.card;if c.definition!=ID||c.face_down||c.owner!=actor||c.controller!=actor||actor>=self.players.len()||!self.mystic_instance_valid(&c.id)||s.region.is_some()||s.source_region_instance.is_some()||s.play_source.is_some()||s.attachment_host_instance.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some(){return Err("修格斯秘社原来源无效".into());}self.mobility_immutable_identity(c)?;if let [Op::MSBQ02Loss{played:Some(p),event:Some(event)}]=ops{if p.card.controller!=actor||catalog::card(&p.card.definition).color!="红"||!self.mystic_instance_valid(&p.card.id)||!self.mystic_instance_valid(event)||p.card.id==c.id{return Err("失控必须具有原红牌打出观察".into());}self.mobility_immutable_identity(&p.card)?;}else if let [Op::MSBQ02TaskWin{scored:Some(cards)}]=ops {if cards.len()<3||cards.iter().map(|c|&c.id).collect::<std::collections::BTreeSet<_>>().len()!=cards.len(){return Err("胜利观察须包含至少三个不同任务".into());}for card in cards{if card.owner!=actor||card.controller!=actor||card.face_down||!self.mystic_instance_valid(&card.id)||catalog::card(&card.definition).kind!="region"||!catalog::card(&card.definition).subtypes.iter().any(|s|s=="任务"){return Err("胜利观察任务身份无效".into());}self.mobility_immutable_identity(card)?;}}else if !matches!(ops,[Op::CostReduction{filter:CardFilter::MSBQ02Command,amount:1}]){return Err("修格斯程序缺完整观察".into());}Ok(())}
 pub(crate) fn msbq02_forced(&mut self,d:&Declaration)->RuleResult<bool>{if d.ability.event!=Some(Event::MSBQ02RedPlayed){return Ok(false);}validate_ability(&d.source.card.definition,&d.ability)?;self.msbq02_source(d.actor,&d.source,&d.ability.ops)?;if !self.players[d.actor].eliminated{let f=self.make_frame(d.actor,d.source.clone(),&d.ability,vec![],vec![],None);self.dispatch_frame(f,d.ability.label.clone(),None,ResponsePolicy::Respondable);}Ok(true)}
 pub(crate) fn validate_msbq02_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID&&!f.ability_key.starts_with("msbq02-")&&!f.steps.iter().any(|s|matches!(s.op,Op::MSBQ02Loss{..}|Op::MSBQ02TaskWin{..}|Op::CostReduction{filter:CardFilter::MSBQ02Command,..})){return Ok(());}let ops=f.steps.iter().map(|s|s.op.clone()).collect::<Vec<_>>();self.msbq02_source(f.actor,&f.source,&ops)?;let mut a=definition().abilities.into_iter().find(|a|a.key==f.ability_key).ok_or("未知修格斯帧")?;a.ops=ops;validate_ability(ID,&a)?;if !f.targets.is_empty()||f.chosen_region.is_some()||!self.mystic_instance_valid(&f.frame_id)||f.steps.iter().any(|s|s.context!=f.actor)||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor>0&&!matches!(f.guard,GuardState::Accepted)||!f.resource_payments.is_empty(){return Err("修格斯帧执行上下文无效".into());}if f.ability_key==HONOR{if !matches!(f.already_paid.as_slice(),[PaidCost::MSBQ02Honor{before}]if *before>=1){return Err("修格斯减费缺真实名誉1".into());}}else if !f.already_paid.is_empty(){return Err("强制失控不得附加费用".into());}Ok(())}
 pub(crate) fn msbq02_loss(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_msbq02_frame(f)?;if f.ability_key!=LOSS||f.cursor!=1{return Err("失控必须由原强制程序消费".into());}if self.players[f.actor].society_zone.card.as_ref().is_some_and(|c|c.id==f.source.card.id){let n=&mut self.players[f.actor].society_zone.loss_control;*n=n.saturating_add(1).min(3);}Ok(())}
 pub(crate) fn validate_msbq02_state(&self)->RuleResult<()>{let mut events=std::collections::BTreeSet::new();let mut remember=|source:&SourceSnapshot,ops:Vec<Op>|->RuleResult<()>{for op in ops{let key=match op{Op::MSBQ02Loss{event:Some(id),..}=>Some((0,id)),Op::MSBQ02TaskWin{scored:Some(cards)}=>cards.last().map(|c|(1,c.id.clone())),_=>None};if let Some(key)=key{if !events.insert((source.card.id.clone(),key)){return Err("同一秘社观察不可重复待处理".into());}}}Ok(())};for e in &self.effects{match e{Effect::Declare{declaration:d}=>remember(&d.source,d.ability.ops.clone())?,Effect::Frame{frame:f}=>remember(&f.source,f.steps.iter().map(|s|s.op.clone()).collect())?,_=>{}}}for item in &self.stack{if let Some(f)=&item.frame{remember(&f.source,f.steps.iter().map(|s|s.op.clone()).collect())?;}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,..}=>remember(&d.source,d.ability.ops.clone())?,ChoiceResolution::Frame{frame:f,..}=>remember(&f.source,f.steps.iter().map(|s|s.op.clone()).collect())?,_=>{}}}
for p in &self.players{if p.society_zone.card.as_ref().is_some_and(|c|c.definition==ID)&&p.society_zone.loss_control>3{return Err("修格斯失控不能超过3".into());}}
 for e in &self.effects{match e{Effect::Frame{frame}=>self.validate_msbq02_frame(frame)?,Effect::Declare{declaration:d}if related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.msbq02_source(d.actor,&d.source,&d.ability.ops)?;},_=>{}}}for s in &self.stack{if s.label==definition().abilities[1].label&&s.frame.as_ref().is_none_or(|f|f.source.card.definition!=ID||f.ability_key!=LOSS){return Err("修格斯强制失控堆叠不能缺少或替换原帧".into());}if let Some(f)=&s.frame{self.validate_msbq02_frame(f)?;}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,..}if d.ability.key==LOSS=>return Err("强制失控不能改成可选声明".into()),ChoiceResolution::Declare{declaration:d,..}if related(&d.ability)=>{validate_ability(&d.source.card.definition,&d.ability)?;self.msbq02_source(d.actor,&d.source,&d.ability.ops)?;},ChoiceResolution::Frame{frame,..}if frame.source.card.definition==ID=>return Err("修格斯固定能力无待选步骤".into()),_=>{}}}Ok(())}
}
